// Draw concentric circles
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

const colors = [
  '#ffd166', // pastel orange
  '#4ecdc4', // pastel teal
  '#45b7d1', // pastel blue
  '#96ceb4', // pastel cyan
  '#feca57', // pastel yellow
  '#ff7ba7'  // pastel rose
];

// Draw circles with gradient effect
for (let i = 0; i < 6; i++) {
  const radius = maxRadius - i * 30;
  const gradient = ctx.createRadialGradient(
    centerX, centerY,
    radius - 20,
    centerX, centerY,
    radius + 20
  );

  const startColor = colors[i % 6];
  const endColor = colors[(i + 1) % 6];

  gradient.addColorStop(0, startColor);
  gradient.addColorStop(1, endColor);

  ctx.fillStyle = gradient;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fill();
}

// Draw radial patterns
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;

// Draw outer ring pattern
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const x1 = centerX + Math.cos(angle) * (maxRadius - 10);
  const y1 = centerY + Math.sin(angle) * (maxRadius - 10);
  const x2 = centerX + Math.cos(angle) * (maxRadius + 10);
  const y2 = centerY + Math.sin(angle) * (maxRadius + 10);

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
}

// Draw inner spiral pattern
for (let i = 0; i < 12; i++) {
  const angle = (i / 12) * Math.PI * 2;
  const radius = maxRadius - i * 8;
  const x = centerX + Math.cos(angle) * radius;
  const y = centerY + Math.sin(angle) * radius;

  if (i > 0) {
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(x, y);
    ctx.stroke();
  }
}

