// Draw spiral in cool tones
const drawSpiral = (x, y, len, angle, depth) => {
    if (depth > 0) {
        // Cool tones
        const r = 100 + depth * 10;
        const g = 150 + depth * 10;
        const b = 200 + depth * 10;

        // Fill arc
        ctx.fillStyle = `rgb(${r}, ${g}, ${b})`;
        ctx.beginPath();
        ctx.arc(x, y, len, 0, Math.PI * 2);
        ctx.fill();

        // Recursive calls for arms
        drawSpiral(x + Math.cos(angle) * len, 
                   y - Math.sin(angle) * len, 
                   len * 0.7, 
                   angle + Math.PI/4, 
                   depth - 1);
        drawSpiral(x + Math.cos(angle) * len, 
                   y - Math.sin(angle) * len, 
                   len * 0.7, 
                   angle - Math.PI/4, 
                   depth - 1);
    }
};

