// Draw spiral shell
ctx.fillStyle = '#8B4513';
ctx.beginPath();
ctx.moveTo(200, 300);
for (let i = 0; i < 20; i++) {
    const radius = i * 8;
    const angle = i * 0.3;
    const x = 200 + Math.cos(angle) * radius;
    const y = 300 - Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
}
ctx.closePath();
ctx.fill();

// Draw spiral shell details
ctx.fillStyle = '#A0522D';
for (let i = 0; i < 15; i++) {
    const radius = (i + 1) * 8;
    const angle = i * 0.3;
    const x = 200 + Math.cos(angle) * radius;
    const y = 300 - Math.sin(angle) * radius;
    ctx.beginPath();
    ctx.arc(x, y, 2, 0, Math.PI * 2);
    ctx.fill();
}

